// Get the full output from the previous node
const fullOutput = $json.output;

// Isolate the main prompt text.
// This splits the string at "OPTIMIZED VEO 3 PROMPT:" and takes everything after it.
// Then it splits that result at "BREAKDOWN:" and takes everything before it.
const cleanPrompt = fullOutput.split('OPTIMIZED VEO 3 PROMPT:')[1].split('BREAKDOWN:')[0].trim();

// Return a valid JavaScript object.
// n8n will automatically convert this to a perfectly formatted JSON string for the request.
return {
  input: {
    prompt: cleanPrompt
  }
}
